package com.astra.tvhome;

import android.content.*;import android.content.pm.*;import android.content.res.XmlResourceParser;import org.xmlpull.v1.XmlPullParser;import org.json.*;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;import java.util.*;
/** Bounded implementation of CleanYourTV's module-card v1 contract; approvals bind package, signer and label. */
final class ModuleRegistry {
    static final class Card {String pkg,activity,label,caption,signer,appLabel,error="",decision="pending";int accent;long decidedAt;boolean shown;}
    static String fold(String s){return s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");}
    static boolean reserved(String s){String key=fold(s);return key.contains("official")||key.contains("verified")||key.startsWith("hdmi")||Arrays.asList("home","settings","inputs","wifi","livetv","applibrary","choosedefaulthome","clock","defaulthome","cleanyourtv","tvvibehack","astra","av").contains(key);}
    static String digest(byte[] bytes)throws Exception{StringBuilder out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
    static List<Card> scan(MainActivity a){ArrayList<Card> cards=new ArrayList<>();if(!a.pref().getBoolean("moduleCards",true))return cards;PackageManager pm=a.getPackageManager();Intent query=new Intent(Intent.ACTION_MAIN).addCategory("com.gathin.tvhome.category.DOCK_CARD");List<ResolveInfo> found=pm.queryIntentActivities(query,PackageManager.GET_META_DATA);Set<String> seen=new HashSet<>();Set<String> leanback=new HashSet<>();for(ResolveInfo r:pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER),0))leanback.add(r.activityInfo.packageName+"/"+r.activityInfo.name);
        for(ResolveInfo r:found){if(cards.size()>=32)break;if(!seen.add(r.activityInfo.packageName))continue;Card card=new Card();ActivityInfo activity=r.activityInfo;card.pkg=activity.packageName;card.activity=activity.name;card.appLabel=r.loadLabel(pm).toString();cards.add(card);
            try{if(!activity.exported||!activity.enabled||!activity.applicationInfo.enabled||!leanback.contains(card.pkg+"/"+card.activity))throw new Exception("卡片必须与已启用的 Leanback 入口相同");int resource=activity.metaData==null?0:activity.metaData.getInt("com.gathin.tvhome.card",0);if(resource==0)throw new Exception("缺少卡片元数据");try(XmlResourceParser xml=pm.getResourcesForApplication(activity.applicationInfo).getXml(resource)){boolean root=false;int events=0;for(int event=xml.getEventType();event!=XmlPullParser.END_DOCUMENT;event=xml.next()){if(++events>64||xml.getDepth()>2)throw new Exception("卡片 XML 超出限制");if(event==XmlPullParser.START_TAG&&!root){if(!xml.getName().equals("card")||(xml.getNamespace()!=null&&!xml.getNamespace().isEmpty())||xml.getAttributeCount()>16||xml.getAttributeIntValue(null,"spec",-1)!=1)throw new Exception("不支持的卡片规范");root=true;card.label=xml.getAttributeValue(null,"label");card.caption=xml.getAttributeValue(null,"caption");if(card.caption==null)card.caption="";String accent=xml.getAttributeValue(null,"accent");if(accent!=null&&!accent.matches("#[0-9a-fA-F]{6}|#[fF]{2}[0-9a-fA-F]{6}"))throw new Exception("无效卡片强调色");card.accent=accent==null?0xff5799ef:android.graphics.Color.parseColor(accent);}}if(!root)throw new Exception("缺少 card 根节点");}
                if(card.label==null||card.label.length()>24||!card.label.matches("[A-Za-z0-9 .&+'-]{1,24}")||!card.label.equals(card.label.trim())||!card.label.matches(".*[A-Za-z0-9].*")||reserved(card.label))throw new Exception("卡片名称不符合规范");if(card.caption.length()>32||!card.caption.matches("[A-Za-z0-9 .&+'-]*")||fold(card.caption).contains("verified")||fold(card.caption).contains("official"))throw new Exception("卡片说明不符合规范");PackageInfo info=pm.getPackageInfo(card.pkg,PackageManager.GET_SIGNING_CERTIFICATES);android.content.pm.Signature[] signers=info.signingInfo==null?null:info.signingInfo.getApkContentsSigners();if(signers==null||signers.length!=1)throw new Exception("需要唯一签名证书");card.signer=digest(signers[0].toByteArray());String saved=a.pref().getString("moduleDecision."+card.pkg,"");if(!saved.isEmpty()){JSONObject record=new JSONObject(saved);if(record.getString("signer").equals(card.signer)&&record.getString("label").equals(fold(card.label))){card.decision=record.getString("decision");card.decidedAt=record.optLong("at",0);}}
                if(card.decision.equals("pending"))for(NativeApp app:a.apps)if(!app.pkg.equals(card.pkg)&&(fold(app.originalName).equals(fold(card.label))||fold(app.originalName).equals(fold(card.appLabel))))throw new Exception("名称与已安装应用冲突");
            }catch(Exception e){card.error=e.getMessage()==null?"无法读取卡片":e.getMessage();}
        }
        cards.sort(Comparator.comparingLong(c->c.decidedAt==0?Long.MAX_VALUE:c.decidedAt));Map<String,Card> names=new HashMap<>();for(Card card:cards){if(!card.error.isEmpty())continue;String key=fold(card.label);Card existing=names.get(key);if(existing!=null){card.error="卡片名称冲突";if(existing.decidedAt==0)existing.error="卡片名称冲突";}else names.put(key,card);}int shown=0;for(Card card:cards)if(card.error.isEmpty()&&card.decision.equals("show")){card.shown=shown++<8;if(!card.shown)card.error="超过 8 张显示卡片的上限";}return cards;
    }
    static void decide(MainActivity a,Card card,boolean show)throws Exception{if(!card.error.isEmpty())throw new IllegalArgumentException(card.error);JSONObject value=new JSONObject().put("signer",card.signer).put("label",fold(card.label)).put("decision",show?"show":"hide").put("at",System.currentTimeMillis());a.pref().edit().putString("moduleDecision."+card.pkg,value.toString()).apply();trim(a);a.applyModulePreferences();}
    static void trim(MainActivity a){ArrayList<String> keys=new ArrayList<>();for(String key:a.pref().getAll().keySet())if(key.startsWith("moduleDecision."))keys.add(key);if(keys.size()<=128)return;keys.sort(Comparator.comparingLong(k->{try{return new JSONObject(a.pref().getString(k,"{}")).optLong("at",0);}catch(Exception e){return 0L;}}));android.content.SharedPreferences.Editor edit=a.pref().edit();for(int i=0;i<keys.size()-128;i++)edit.remove(keys.get(i));edit.apply();}
}
